import sys, os; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from patchlib import patch, SRC
p = os.path.join(SRC, '13_m01_index.js'); t = open(p, encoding='utf-8').read()
a = t.find('  /* ---- weather ---- */'); b = t.find('  /* ---- insurance ---- */')
assert a > 0 and b > a
NEW = r"""  /* ---- weather (names and meanings as HAZARD_SCHEMA.md fixes them; a layer whose column is not merged yet is not offered) ---- */
  const qn = (col, what) => ZC.includes(col) ? ` The data grades each ZIP's ${what} A to D by how near and how alike the stations are.` : '';
  lay('ar_days', { l: 'Atmospheric river days a year, AR2 or stronger', grp: 'Weather', dir: 1, ramp: 'teal', g: 'B', f: d1, note: 'Days a year with an atmospheric river of AR2 or stronger (CW3E scale) overhead at the nearest of twenty coast points, from the landfall catalogue. Grade B at the coast, C inland, where the mountains have already wrung out part of the storm. These are the leak making storms: long, warm, wind driven rain.' });
  lay('ar_d', { l: 'Atmospheric river days a year, all ranks', grp: 'Weather', dir: 1, ramp: 'teal', g: 'B', f: d1, note: 'Hours with an atmospheric river of any rank overhead at the nearest coast point, divided by 24, a year. AR1 is mostly beneficial rain; the roof damage comes from AR3 and up (next layer).' });
  lay('ar3_d', { l: 'Atmospheric river days a year, AR3 or stronger', grp: 'Weather', dir: 1, ramp: 'teal', g: 'B', f: v => D(v, 2), note: 'The strong ones: AR3, AR4 and AR5 days a year at the nearest coast point. One of the four weights the storm line is spread by.' });
  lay('ar45_dec', { l: 'AR4 and AR5 landfalls a decade', grp: 'Weather', dir: 1, ramp: 'teal', g: 'B', f: d1, note: 'Extreme and exceptional atmospheric rivers at the nearest coast point, events a decade.' });
  lay('rain_in', { l: 'Normal rain a year (inches)', grp: 'Weather', dir: 1, ramp: 'teal', g: 'A', f: d1, note: 'NOAA 1991 to 2020 normal annual precipitation at the stations nearest the ZIP\'s town point, with distance stretched for elevation difference. Grade A at a station, B between stations. Nearly all of it falls November to March.' + qn('rain_q', 'rain normal') });
  lay('rain_d1', { l: 'Heavy rain days a year (1 inch or more)', grp: 'Weather', dir: 1, ramp: 'teal', g: 'B', f: d1, note: 'Days a year with 1.00 inch of rain or more: the normals\' day counts where the station has them, else its daily record. An inch in a day finds every weak flashing and ponds every flat roof.' });
  lay('rain_d2', { l: 'Very heavy rain days a year (2 inches or more)', grp: 'Weather', dir: 1, ramp: 'teal', g: 'B', f: v => D(v, 2), note: 'Days a year with 2.00 inches or more at the same stations. One of the weights of the storm line.' });
  lay('rain_wet_in', { l: 'Normal rain in the wettest month (inches)', grp: 'Weather', dir: 1, ramp: 'teal', g: 'A', f: d1, note: 'The wettest month of the normal year and its normal rain: how hard the wet season peaks.' });
  lay('g58', { l: 'Gust days a year, 58 mph or more (nearest screened station)', grp: 'Weather', dir: 1, ramp: 'teal', g: 'B', f: v => D(v, 2), note: 'Days a year with a peak gust of 58 mph or more at the nearest station that passed the screening rules (141 sites, airport summaries 2002 to 2025 or GHCN Daily 1996 to 2025). Not blended between stations: wind is local. Grade A at an airport, C far from one.' + qn('gust_q', 'gust figure') });
  lay('g40', { l: 'Gust days a year, 40 mph or more (nearest screened station)', grp: 'Weather', dir: 1, ramp: 'teal', g: 'B', f: d1, note: 'The lower threshold at the same station: the wind that lifts aged shingles and loose tile.' });
  lay('g75', { l: 'Gust days a year, 75 mph or more (nearest screened station)', grp: 'Weather', dir: 1, ramp: 'teal', g: 'B', f: v => D(v, 2), note: 'Hurricane force gusts at the same station: rare outside the passes, ridges and the far north coast.' });
  lay('wd58', { l: 'Days a year a gust of 58 mph or more was measured within 25 miles', grp: 'Weather', dir: 1, ramp: 'teal', g: 'B', f: d1, note: 'Distinct days, 2010 to 2025, with a measured gust report of 58 mph or more within 25 miles of the town point in the NWS Local Storm Reports. Mountain and canyon sensors dominate, so read it as "strong wind was measured nearby", not as wind at the house.' });
  lay('hw_yr', { l: 'High Wind days a year in the forecast zone', grp: 'Weather', dir: 1, ramp: 'teal', g: 'B', f: d1, note: 'Distinct days with a Storm Events "High Wind" record in the NWS forecast zone that holds the ZIP, 2006 to 2025.' });
  lay('off_cls', { l: 'Offshore wind exposure (Santa Ana, Diablo, sundowner), class 0 to 3', grp: 'Weather', dir: 1, ramp: 'teal', g: 'C', f: v => isN(v) ? ['none', 'occasional', 'regular', 'frequent'][v] || D(v, 0) : '—', note: 'From Storm Events episodes 2006 to 2025 whose narrative names a Santa Ana, Diablo or sundowner wind in the ZIP\'s forecast zone: 0 none, 1 occasional (1 to 4 episodes in 20 years), 2 regular (5 to 19), 3 frequent (20 or more). A lower bound: an episode whose narrative does not name the wind is not counted. Offshore wind strips roofs and carries the fires.' });
  lay('h100', { l: 'Days a year at 100°F or more', grp: 'Weather', dir: 1, ramp: 'teal', g: 'A', f: d1, note: 'Daily maximum temperatures 1996 to 2025 at the three nearest stations by effective distance (elevation and distance to the sea both count). Heat and sun age asphalt, set the cool roof and coatings market, and bring Cal/OSHA\'s heat rules onto the job.' + qn('heat_q', 'heat figure') });
  lay('h90', { l: 'Days a year at 90°F or more', grp: 'Weather', dir: 1, ramp: 'teal', g: 'A', f: d1, note: 'The same stations at 90°F.' });
  lay('h110', { l: 'Days a year at 110°F or more', grp: 'Weather', dir: 1, ramp: 'teal', g: 'A', f: d1, note: 'The same stations at 110°F: the desert and the south end of the Central Valley. Crews start before dawn or do not work.' });
  lay('tjul', { l: 'Normal July afternoon high (°F)', grp: 'Weather', dir: 1, ramp: 'teal', g: 'A', f: v => D(v, 0), note: '1991 to 2020 normal July daily maximum. Low values on the coast mark the marine layer: cool, damp roofs with moss and slow drying.' });
  lay('snow_psf', { l: 'Design ground snow load (pounds per square foot)', grp: 'Weather', dir: 1, ramp: 'teal', g: 'B', f: v => D(v, 0), note: 'ASCE 7-22 ground snow load, Risk Category II, at the town point. A reliability target load, far above what a typical winter brings, and the ridge above the town carries more. In the Sierra and the far north it decides the covering, the fastening and the ice barrier.' });
  lay('snowfall_in', { l: 'Normal snowfall a year (inches)', grp: 'Weather', dir: 1, ramp: 'teal', g: 'A', f: d1, note: '1991 to 2020 normal snowfall at the nearest station that has one within 30 km effective distance; blank elsewhere.' });
  lay('hail1_n25', { l: 'Hail reports of 1 inch or more within 25 miles, 1955 to 2025', grp: 'Weather', dir: 1, ramp: 'teal', g: 'A', f: n0, note: 'Hail is rare in California: 349 reports of an inch or more anywhere in the state since 1951. Shown so nobody plans a hail campaign here.' });
  lay('coast_km', { l: 'Distance to salt water (km)', grp: 'Weather', dir: -1, ramp: 'teal', g: 'A', f: d1, note: 'From the ZIP\'s town point to the nearest salt water shore: the Pacific, San Francisco, San Pablo and Suisun bays and the smaller bays. Salt air shortens the life of fasteners, flashing and some metal panels; the marine layer keeps roofs damp on the north coast.' });
  lay('elev_pt_m', { l: 'Elevation at the town point (meters)', grp: 'Weather', dir: 1, ramp: 'teal', g: 'A', f: n0, note: 'Ground elevation at the ZIP\'s town point. With latitude it sets snow, freeze and the length of the roofing season.' });
  lay('storm_x', { l: 'Wind and rain exposure index (the storm line\'s spread)', grp: 'Weather', dir: 1, ramp: 'teal', g: 'C', f: v => D(v, 2), note: 'The index the storm line is spread over ZIPs by, times 1,000: a floor plus weights on gust days of 58 and 75 mph, AR3 or stronger days and days of 2 inches of rain. The weights are the data build\'s choices (module 04 lists them).' });
  lay('stress', { l: 'Roof weather stress score (0 to 100, a ranking aid)', grp: 'Weather', dir: 1, ramp: 'teal', g: 'D', f: v => D(v, 0), note: 'A weighted sum of six parts (rain 25, wind 25, fire 25, heat 10, snow 10, salt 5), each capped. Every weight is a choice. A ranking aid for where roofs have the hardest life, not a physical quantity.' });
"""
t = t[:a] + NEW + t[b:]
open(p, 'w', encoding='utf-8').write(t)
patch('13_m01_index.js', [
 ("""  lay(HC.fhsz, { l: 'Homes in a High or Very High Fire Hazard Severity Zone (%)', grp: 'Wildfire', dir: 1, ramp: 'green', g: 'B', f: p0, note: 'CAL FIRE Fire Hazard Severity Zones laid over the ZIP.""",
  """  lay(HC.fhsz, { l: 'Land in a High or Very High Fire Hazard Severity Zone (% of the ZIP)', grp: 'Wildfire', dir: 1, ramp: 'green', g: 'A', f: p0, note: 'Share of the ZIP\\'s area inside a High or Very High Fire Hazard Severity Zone: the State Responsibility Area map of April 1, 2024 and the State Fire Marshal\\'s Local Responsibility Area map of March 24, 2025 (a city\\'s adopted map can differ). Area, not homes: in a ZIP of open hills the homes may sit outside the zone."""),
 ("""  lay(HC.fhszvh, { l: 'Homes in a Very High Fire Hazard Severity Zone (%)', grp: 'Wildfire', dir: 1, ramp: 'green', g: 'B', f: p0, note: 'The Very High class alone.' });""",
  """  lay(HC.fhszvh, { l: 'Land in a Very High Fire Hazard Severity Zone (% of the ZIP)', grp: 'Wildfire', dir: 1, ramp: 'green', g: 'A', f: p0, note: 'The Very High class alone, same maps.' });
  lay('fhsz_any', { l: 'Land in any Fire Hazard Severity Zone (% of the ZIP)', grp: 'Wildfire', dir: 1, ramp: 'green', g: 'A', f: p0, note: 'Moderate, High and Very High together.' });
  lay('burn_sh', { l: 'Land burned since 2000 (% of the ZIP)', grp: 'Wildfire', dir: 1, ramp: 'green', g: 'A', f: p0, note: 'Share of the ZIP inside any CAL FIRE historic fire perimeter of 10 acres or more, 2000 to 2025 (reburns count once).' });
  lay('fire_n', { l: 'Fire perimeters touching the ZIP, 2000 to 2025', grp: 'Wildfire', dir: 1, ramp: 'green', g: 'A', f: n0, note: 'Perimeters of 10 acres or more with at least one acre inside the ZIP (CAL FIRE historic perimeters).' });
  lay('fire_km', { l: 'Distance to the nearest fire perimeter since 2000 (km)', grp: 'Wildfire', dir: -1, ramp: 'green', g: 'A', f: d1, note: 'From the town point to the nearest perimeter of 10 acres or more; zero inside one.' });"""),
 ("""  lay(HC.dest, { l: 'Structures destroyed by wildfire, all years on record', grp: 'Wildfire', dir: 1, ramp: 'green', g: 'A', f: n0, note: 'CAL FIRE damage inspections (DINS): structures the inspectors recorded as destroyed, placed in the ZIP by their coordinates. Observed, not modeled. The record starts in 2013 and covers fires CAL FIRE inspected.' });
  lay(HC.dmg, { l: 'Structures damaged by wildfire, all years on record', grp: 'Wildfire', dir: 1, ramp: 'green', g: 'A', f: n0, note: 'The same inspections: structures with damage short of destroyed (affected, minor, major). These are the roof repair and partial reroof jobs after a fire.' });""",
  """  lay(HC.dest, { l: 'Structures destroyed by wildfire, 2013 to 2025', grp: 'Wildfire', dir: 1, ramp: 'green', g: 'A', f: n0, note: 'CAL FIRE damage inspections (DINS): structures the inspectors recorded as destroyed (more than half), placed in the ZIP by their coordinates. Observed, not modeled. The record starts in 2013 and covers fires CAL FIRE inspected.' });
  lay(HC.dmg, { l: 'Structures damaged by wildfire, 2013 to 2025', grp: 'Wildfire', dir: 1, ramp: 'green', g: 'A', f: n0, note: 'The same inspections: structures with damage short of destroyed (affected, minor, major). These are the roof repair and partial reroof jobs after a fire.' });
  lay('fire_dest_res', { l: 'Residences destroyed by wildfire, 2013 to 2025', grp: 'Wildfire', dir: 1, ramp: 'green', g: 'A', f: n0, note: 'The same inspections, residential structure types only (single family, multifamily, mobile home, mixed).' });
  lay('fire_nxt', { l: 'Wildfire rebuild and repair roofs, next twelve months (model)', grp: 'Wildfire', dir: 1, ramp: 'green', g: 'D', f: v => D(v, 0), note: 'Forty percent of the residences destroyed in 2022 to 2025, a quarter of them each year, plus half the residences damaged in 2025. The rebuild share is an assumption.' });"""),
 ("""  lay(HC.solar, { l: 'Homes with rooftop solar (% of one unit homes)', grp: 'Roof covering', dir: 1, ramp: 'teal', g: 'C', f: p0, note: 'The share behind the solar detach and reset line: a reroof under panels needs them taken off and put back. Source and vintage are in the data build record (module 04).' });""",
  """  lay(HC.solar, { l: 'Homes with rooftop solar (% of one unit homes)', grp: 'Roof covering', dir: 1, ramp: 'teal', g: 'B', f: p0, note: 'California Distributed Generation Statistics: interconnected residential solar sites to September 30, 2026 in the territories of PG&E, Edison and SDG&E, over one unit homes, capped at 80 percent. Where a city or district utility serves the ZIP (Los Angeles DWP, SMUD and others) the file has nothing and the ZIP takes its county\\'s share from covered ZIPs: an estimate there. A reroof under panels needs them taken off and put back.' });
  lay('solar_n', { l: 'Homes with rooftop solar (count)', grp: 'Roof covering', dir: 1, ramp: 'teal', g: 'B', f: n0, note: 'The same file, distinct interconnected residential sites; estimated where a public utility serves the ZIP.' });"""),
])
